package com.starry.magic.menu;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.graphics.Canvas;
import android.graphics.Matrix;
import android.graphics.Paint;
import android.graphics.Rect;
import android.graphics.RectF;
import android.graphics.drawable.Drawable;
import android.util.Base64;
import android.util.Log;

/**
 * 菜单边框：四角 + 上中 + 下中 + 左中/右中。
 *
 * 2026-11-22 重构：几何参数收进 {@link Geo}，**菜单与公告各用一套**（MENU_GEO / ANNOUNCE_GEO），
 * 互不影响 —— 公告卡比主面板小得多，共用一套绝对尺寸时左右中会跑到卡外、下中整体溢出。
 *
 * 素材一律整图等比嵌入式显示，不裁剪、不拉伸；宽高比由素材原始比例决定：
 *   corner 500x440 视窗（原图 440x440 + 60px 透明补边）、top 680x247、bottom 720x360、side 400x600。
 */
public final class MenuFrameRes {

    private static final String TAG = "MenuFrame";
    /** 设计画布宽（352dp@3x），比例尺 k = 画布宽 / (DW + 2*padSide) */
    private static final int DW = 1056;
    private static final int FRAME_ALPHA = 255;

    /**
     * 一套边框几何。**单位约定（2026-11-22 统一）**：
     *   位置类（pad 系列、overhang、shift 系列、cornerDx / cornerDy、topDyPx、bottomDyPx、sideDx 系列）＝ 实际屏幕 px，直接用；
     *   尺寸类（cornerW/H）与比例类（各 Frac 字段）＝ 设计画布 px / 占面板比例，乘 k。
     * 这样「报 30 就移动 30px」，且改留白不会改变 k、不会改变边框大小。
     */
    public static final class Geo {
        /** 日志用标识（menu / announce） */
        public String name = "menu";
        /** 是否已打印过一次几何日志 */
        public boolean logged = false;
        /** true=以卡片本体为基准（公告）；false=以外壳为基准（菜单，四角就在外探区） */
        public boolean baseOnCard = false;
        /** 窗口四周留白（设计 px）：边框层靠负 margin 溢进这块空间 */
        public float padTop = 21f;
        public float padSide = 21f;
        public float padBottom = 75f;
        /** 面板外探（card 到外壳的距离，22dp@3x=66px） */
        public float overhang = 66f;
        /** 四角：显示尺寸 + 横向外移 + 上角下移 / 下角上移 */
        public float cornerW = 500f;
        public float cornerH = 440f;
        public float cornerDx = 78f;
        /** 下排横向外移（默认同上排；公告要求上下排分开调） */
        public float cornerDxBottom = 78f;
        public float cornerDyTop = 9f;
        public float cornerDyBottom = 8f;
        /** 上中：宽度占面板比例 + 纵向偏移（相对自身高度）+ 额外位移（设计 px，正=向下） */
        public float topWFrac = 0.55f;
        public float topYFrac = -0.094f;
        public float topDyPx = 0f;
        /** 下中：宽度占面板比例 + 纵向偏移（设计 px，正=向下） */
        public float bottomWFrac = 0.55f;
        public float bottomDyPx = 75f;
        /** 左右中：宽度占面板比例 + 垂直位置（0=顶,0.5=中,1=底）+ 各自横向偏移 */
        public float sideWFrac = 0.33f;
        public float sideYFrac = 0.5f;
        public float sideDxLeft = 0f;
        public float sideDxRight = 0f;
        /** 整层平移（设计 px），用于公告这类需要整体挪动的场景 */
        public float shiftX = 0f;
        public float shiftY = 0f;
    }

    /** 主菜单：现行定稿参数 */
    public static final Geo MENU_GEO = buildMenuGeo();

    /** 主菜单几何：下排横向外移与上排同值（保持既有行为） */
    private static Geo buildMenuGeo() {
        Geo g = new Geo();
        // 实际 px（= 原设计值 × k≈1.154），保证与改造前视觉一致
        g.padTop = 25f;
        g.padSide = 25f;
        g.padBottom = 88f;
        g.overhang = 77f;
        g.cornerDx = 90f;
        g.cornerDxBottom = 90f;
        g.cornerDyTop = 10f;
        g.cornerDyBottom = 9f;
        g.bottomDyPx = 87f;
        g.topDyPx = 0f;
        return g;
    }

    /** 公告卡：独立的缩小版几何（卡片小、高度矮，各元素按比例收），与菜单互不影响 */
    private static Geo buildAnnounceGeo() {
        Geo g = new Geo();
        g.padTop = 100f;
        g.padSide = 25f;
        g.padBottom = 169f;
        g.overhang = 77f;
        // 尺寸/比例
        g.cornerW = 420f;
        g.cornerH = 369.6f;
        g.topWFrac = 0.58f;
        g.topYFrac = -0.094f;
        g.bottomWFrac = 0.58f;
        g.sideWFrac = 0.19f;
        g.sideYFrac = 0.5f;
        // 位置（实际 px，= 改造前视觉位置）
        g.cornerDx = 147f;
        g.cornerDxBottom = 150f;
        g.cornerDyTop = -57f;
        g.cornerDyBottom = -60f;
        g.topDyPx = -93f;
        g.bottomDyPx = 165f;
        g.sideDxLeft = -78f;
        g.sideDxRight = 78f;
        g.shiftX = 0f;
        g.shiftY = 0f;
        g.name = "announce";
        g.baseOnCard = true;
        return g;
    }

    public static final Geo ANNOUNCE_GEO = buildAnnounceGeo();

    /** 四角素材 500x440（含左侧 60px 透明补边），四块镜像复用 */
    private static final String CORNER_B64 = "";
    /** 上中 680x247 */
    private static final String TOP_B64 = "";
    /** 下中 720x360（原图 1774x887 整图等比） */
    private static final String BOTTOM_B64 = "";
    /** 侧边 400x600（原图 1024x1536 整图等比），右中用水平镜像 */
    private static final String SIDE_B64 = "";

    /** 素材原始宽高比（显示时只按宽度缩放，高度=宽*比例 ⇒ 永不拉伸） */
    private static final float CORNER_ASPECT = 440f / 500f;
    private static final float TOP_ASPECT = 247f / 680f;
    private static final float BOTTOM_ASPECT = 360f / 720f;
    private static final float SIDE_ASPECT = 600f / 400f;

    private static Bitmap sCorner, sCornerH, sCornerV, sCornerHV, sTop, sBottom;
    private static Bitmap sSide, sSideH;
    private static boolean sLogged;

    private MenuFrameRes() {
    }

    /** 主菜单默认几何 */
    public static Drawable frameBg() {
        return new FrameDrawable(MENU_GEO);
    }

    /** 指定几何（公告等） */
    public static Drawable frameBg(Geo geo) {
        return new FrameDrawable(geo != null ? geo : MENU_GEO);
    }

    private static Bitmap dec(String b64) {
        try {
            byte[] raw = Base64.decode(b64, Base64.DEFAULT);
            Bitmap b = BitmapFactory.decodeByteArray(raw, 0, raw.length);
            if (b == null) {
                Log.e(TAG, "decode null, bytes=" + raw.length);
            }
            return b;
        } catch (Throwable t) {
            Log.e(TAG, "decode failed: " + t);
            return null;
        }
    }

    private static Bitmap flip(Bitmap src, boolean h, boolean v) {
        if (src == null) {
            return null;
        }
        try {
            Matrix m = new Matrix();
            m.setScale(h ? -1f : 1f, v ? -1f : 1f);
            return Bitmap.createBitmap(src, 0, 0, src.getWidth(), src.getHeight(), m, true);
        } catch (Throwable t) {
            Log.w(TAG, "flip failed: " + t);
            return src;
        }
    }

    private static synchronized void ensure() {
        if (sCorner == null) {
            sCorner = dec(CORNER_B64);
            sCornerH = flip(sCorner, true, false);
            sCornerV = flip(sCorner, false, true);
            sCornerHV = flip(sCorner, true, true);
        }
        if (sTop == null) {
            sTop = dec(TOP_B64);
        }
        if (sBottom == null) {
            sBottom = dec(BOTTOM_B64);
        }
        if (sSide == null) {
            sSide = dec(SIDE_B64);
            sSideH = flip(sSide, true, false);
        }
        if (!sLogged) {
            sLogged = true;
            Log.i(TAG, "corner " + stat(sCorner) + " | top " + stat(sTop)
                    + " | bottom " + stat(sBottom) + " | side " + stat(sSide));
        }
    }

    private static String stat(Bitmap b) {
        if (b == null) {
            return "null";
        }
        int w = b.getWidth();
        int h = b.getHeight();
        int total = w * h;
        int transparent = 0;
        int opaque = 0;
        int[] row = new int[w];
        for (int y = 0; y < h; y++) {
            b.getPixels(row, 0, w, 0, y, w, 1);
            for (int x = 0; x < w; x++) {
                int a = row[x] >>> 24;
                if (a < 8) {
                    transparent++;
                } else if (a >= 250) {
                    opaque++;
                }
            }
        }
        return w + "x" + h + " transparent=" + (100 * transparent / total) + "% opaque=" + (100 * opaque / total) + "%";
    }

    private static final class FrameDrawable extends Drawable {

        private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG | Paint.FILTER_BITMAP_FLAG);
        private final RectF box = new RectF();
        private final Geo g;

        FrameDrawable(Geo geo) {
            this.g = geo;
            paint.setAlpha(FRAME_ALPHA);
        }

        @Override
        public void draw(Canvas c) {
            ensure();
            Rect b = getBounds();
            if (b.isEmpty() || sCorner == null) {
                return;
            }
            final float w = b.width();
            final float h = b.height();
            // 位置类 = 实际 px（直接用）；尺寸类 = 设计 px，乘 k
            final float padTop = g.padTop;
            final float padSide = g.padSide;
            final float padBottom = g.padBottom;
            final float oh = g.overhang;
            // k 只由「可用宽 / 设计画布宽」决定：改留白不再改变边框尺寸
            final float k = Math.max(0.01f, (w - 2f * padSide) / DW);
            final float cw = g.cornerW * k;
            final float ch = g.cornerH * k;
            final float dx = g.cornerDx;
            final float dxB = g.cornerDxBottom;
            final float dyT = g.cornerDyTop;
            final float dyB = g.cornerDyBottom;
            // baseOnCard：公告以卡片本体为准（四角/下中贴卡边、左右中相对卡居中）
            final float baseShift = g.baseOnCard ? oh : 0f;
            final float top0 = b.top + padTop + g.shiftY + baseShift;
            final float left0 = b.left + padSide + g.shiftX + baseShift;
            final float ph = h - padTop - padBottom - baseShift * 2f;
            final float pw = w - padSide * 2f - baseShift * 2f;

            // 左中 / 右中先画（最底层）：以面板本体左右边缘为基准居中，越界夹回保证可见
            if (sSide != null) {
                final float sw = pw * g.sideWFrac;
                final float sh = sw * SIDE_ASPECT;
                final float sy = top0 + (ph - sh) * g.sideYFrac;
                final float sdxL = g.sideDxLeft;
                final float sdxR = g.sideDxRight;
                final float keep = sw * 0.5f;
                float lx = left0 + oh - sw * 0.5f + sdxL;
                float rx = left0 + pw - oh - sw * 0.5f + sdxR;
                lx = Math.max(-keep, Math.min(lx, w - keep));
                rx = Math.max(-keep, Math.min(rx, w - keep));
                blit(c, sSide, lx, sy, sw, sh);
                blit(c, sSideH, rx, sy, sw, sh);
            }

            // 四角其次
            blit(c, sCorner, left0 - dx, top0 + dyT, cw, ch);
            blit(c, sCornerH, left0 + pw - cw + dx, top0 + dyT, cw, ch);
            blit(c, sCornerV, left0 - dxB, top0 + ph - ch - dyB, cw, ch);
            blit(c, sCornerHV, left0 + pw - cw + dxB, top0 + ph - ch - dyB, cw, ch);

            // 下中：压在四角之上
            if (sBottom != null) {
                final float bw = pw * g.bottomWFrac;
                final float bh = bw * BOTTOM_ASPECT;
                blit(c, sBottom, left0 + (pw - bw) * 0.5f,
                        top0 + ph - bh + g.bottomDyPx, bw, bh);
            }

            // 上中最后画：压在最上层
            if (sTop != null) {
                final float topW = pw * g.topWFrac;
                final float topH = topW * TOP_ASPECT;
                blit(c, sTop, left0 + (pw - topW) * 0.5f,
                        top0 + topH * g.topYFrac + g.topDyPx, topW, topH);
            }

            if (!g.logged) {
                g.logged = true;
                Log.i(TAG, "geo[" + g.name + "] win=" + (int) w + "x" + (int) h
                        + " k=" + String.format(java.util.Locale.US, "%.3f", k)
                        + " top0=" + (int) top0 + " left0=" + (int) left0
                        + " pw=" + (int) pw + " ph=" + (int) ph + " oh=" + (int) oh
                        + " | corner=" + (int) cw + "x" + (int) ch + " dx=" + (int) dx
                        + " dyT=" + (int) dyT + " dyB=" + (int) dyB
                        + " | bottom=" + (int) (pw * g.bottomWFrac) + "x"
                        + (int) (pw * g.bottomWFrac * BOTTOM_ASPECT)
                        + " y=" + (int) (top0 + ph - pw * g.bottomWFrac * BOTTOM_ASPECT
                        + g.bottomDyPx)
                        + " | side=" + (int) (pw * g.sideWFrac) + "x"
                        + (int) (pw * g.sideWFrac * SIDE_ASPECT)
                        + " y=" + (int) (top0 + (ph - pw * g.sideWFrac * SIDE_ASPECT) * g.sideYFrac));
            }
        }

        private void blit(Canvas c, Bitmap bmp, float x, float y, float w, float h) {
            if (bmp == null || w <= 0 || h <= 0) {
                return;
            }
            box.set(x, y, x + w, y + h);
            c.drawBitmap(bmp, null, box, paint);
        }

        @Override
        public void setAlpha(int alpha) {
            paint.setAlpha(alpha);
            invalidateSelf();
        }

        @Override
        public void setColorFilter(android.graphics.ColorFilter cf) {
            paint.setColorFilter(cf);
        }

        @Override
        public int getOpacity() {
            return android.graphics.PixelFormat.TRANSLUCENT;
        }
    }
}
